/** Standalone harness (port 9703): farm fixture with its checklist regenerated by the shared generator, a few ticks, no API (ticks fall back to localStorage). */
import {createRoot} from 'react-dom/client';
import '@fontsource/archivo/400.css';
import '@fontsource/archivo/600.css';
import '@fontsource/ibm-plex-mono/400.css';
import '../../../design/tokens.css';
import {proActions} from '../../api/spec-store';
import {devSpec} from '../../workspace/dev-fixture';
import {buildChecklist} from '../../../../../../packages/pro-tools/impl/checklist';
import {ChecklistPanel} from '../ChecklistPanel';
import type {Tick} from '../model';

const spec={...devSpec,checklist:buildChecklist(devSpec)};
proActions.setSpec('dev-farm-ck',1,spec);
const pick=(re:RegExp)=>spec.checklist.filter(i=>re.test(i.id));
const seed:Record<string,Tick>={};
for(const i of pick(/^procure:/))seed[i.id]={itemId:i.id,state:'ticked',by:'human',at:'2026-10-14T13:52:00Z'};
for(const i of pick(/^flash:node-melon$|^wire:node-melon/).slice(0,4))seed[i.id]={itemId:i.id,state:'ticked',by:'human',at:'2026-10-14T13:55:00Z'};
for(const i of pick(/^flash:node-mango$/))seed[i.id]={itemId:i.id,state:'ticked',by:'evidence',evidenceRef:'flash:node-mango#sha',at:'2026-10-14T14:20:00Z'};
if(!localStorage.getItem('pro-ticks:dev-farm-ck'))localStorage.setItem('pro-ticks:dev-farm-ck',JSON.stringify(seed));
createRoot(document.getElementById('root')!).render(<div style={{height:'100vh'}}><ChecklistPanel/></div>);
